const fs=require('fs'), z=require('zlib'), crypto=require('crypto'), assert=require('assert/strict'), {Readable}=require('stream'), Parser=require('jsonparse');
(async()=>{const manifest=JSON.parse(fs.readFileSync('docs/material-input-equivalence-audit.json')); const payload=fs.readFileSync('docs/'+manifest.payload), hash=x=>crypto.createHash('sha256').update(x).digest('hex'); assert.equal(hash(payload),manifest.compressedSha256); const p=new Parser(), out={summary:null,rows:[]};let done=false;p.onValue=function(v){const top=this.stack[1]?.key??(this.stack.length===1?this.key:undefined);if(this.stack.length===2&&top==='discrepancies'){out.rows.push(v);delete this.value[this.key];}else if(this.stack.length===1){if(this.key==='summary')out.summary=v;if(this.key==='discrepancies')done=true;delete this.value[this.key];}else if(this.value&&!['summary','discrepancies'].includes(top))delete this.value[this.key];};for await(const b of Readable.from([payload]).pipe(z.createGunzip())){p.write(b);if(done)break;}assert.ok(done);const projection=out.rows.map(r=>({family:r.family,element:r.element,property:r.property,reference:r.reference,astylar:r.astylar,occurrences:r.occurrences,cases:r.cases,states:r.states}));const candidateOnly=out.rows.filter(r=>r.family==='slider'&&['slider-start','slider-primary'].includes(r.element)&&['paddingTop','paddingRight','paddingBottom','paddingLeft','boxSizing'].includes(r.property));console.log(JSON.stringify({compressedSha256:manifest.compressedSha256,summary:out.summary,allOriginalValuesAndCasesSha256:hash(JSON.stringify(projection)),allOtherRowsSha256:hash(JSON.stringify(out.rows.filter(r=>!candidateOnly.includes(r)))),candidateOnlyGroups:candidateOnly.length,candidateOnlyOccurrences:candidateOnly.reduce((n,r)=>n+r.occurrences,0),candidateOnlyAttributions:[...new Set(candidateOnly.map(r=>r.attribution))]},null,2));})();
