(async()=>{const mf='docs/material-input-equivalence-audit.json',mb=fs.readFileSync(mf),m=JSON.parse(mb),pb=fs.readFileSync('docs/'+m.payload),hash=b=>c.createHash('sha256').update(b).digest('hex');assert.equal(pb.length,m.compressedBytes);assert.equal(hash(pb),m.compressedSha256);const digest=c.createHash('sha256');let length=0,parsed=false,sourceFingerprints;const p=new Parser();p.onValue=function(v){const top=this.stack[1]?.key??(this.stack.length===1?this.key:undefined);if(this.stack.length===1){if(this.key==='sourceFingerprints'){sourceFingerprints=v;parsed=true;}delete this.value[this.key];}else if(this.value&&top!=='sourceFingerprints')delete this.value[this.key];};for await(const b of Readable.from([pb]).pipe(z.createGunzip())){digest.update(b);length+=b.length;if(!parsed)p.write(b);}assert.equal(length,m.uncompressedBytes);assert.equal(digest.digest('hex'),m.uncompressedSha256);let exact=0,lfNormalized=0;for(const f of sourceFingerprints){const b=fs.readFileSync(f.file);if(hash(b)===f.sha256)exact++;else {assert.equal(hash(b.toString().replace(/\r\n/g,'\n')),f.sha256,f.file);lfNormalized++;}}const md='docs/material-input-equivalence-audit.md',mdb=fs.readFileSync(md),raw='artifacts/material-parity/current-ancestry-audit/latest-report.json';assert.equal(hash(fs.readFileSync(raw)),'b07ef154485619ce57fdeb25727476077205c1f656430bc32fdc591ed034f93a');console.log(JSON.stringify({manifest:{file:mf,bytes:mb.length,sha256:hash(mb)},payload:{file:'docs/'+m.payload,bytes:pb.length,sha256:hash(pb)},uncompressed:{bytes:length,sha256:m.uncompressedSha256},markdown:{file:md,bytes:mdb.length,sha256:hash(mdb)},verifiedSourceFingerprints:sourceFingerprints.length,exactByteFingerprints:exact,lfNormalizedFingerprints:lfNormalized,originalCaptureUnchanged:true},null,2));})();
